function defaultFx(){return {brightness:100,contrast:100,saturation:100,hue:0,blur:0,opacity:100,scale:100,x:0,y:0,rotation:0,speed:1,grain:0,vignette:0,sepia:0,grayscale:0,scanlines:0,glitch:0};}
